async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then(response => response.json()),
      fetch('/api/notifications').then(response => response.json()),
      fetch('/api/settings').then(response => response.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { activeUsers: 0, totalRevenue: 0, uptime: '0%' },
      notifications: [],
      settings: { locale: 'en', alertsEnabled: false }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>
      <p>Active users: {analytics.activeUsers}</p>
      <p>Total revenue: {analytics.totalRevenue}</p>
      <p>Uptime: {analytics.uptime}</p>
      <p>Notifications: {notifications.length}</p>
      <p>Locale: {settings.locale}</p>
      <p>Alerts enabled: {settings.alertsEnabled ? 'Yes' : 'No'}</p>
    </div>
  );
}
